// ROOM bath 1 (interior designer): hall bathroom, white quartz, windowless. Inner air [26,2,14,27,4,16]: two cells
// wide, three deep. The door is at (25,2..3,15) on the west wall, so the row z=15 is the walkway and every fixture sits
// on a wall-side row: tub on the north row (z=14), basin and WC on the south row (z=16), a sea_lantern over the tub.
// bath_fit (vocab) puts its water on z=15, which would block the only walkway, so the tub is built here.
import { CAULDRON, GLASS_PANE, SEA_LANTERN, SMOOTH_QUARTZ, SMOOTH_QUARTZ_STAIRS, WATER } from "../vocab.mjs";

export function build(g) {
  // tub: a white quartz box on the north row, water flush with its top (y=3); the walkway at z=15 stays clear
  for (const x of [26, 27]) {
    g.set(x, 2, 14, SMOOTH_QUARTZ);
    g.set(x, 3, 14, WATER);
  }
  // basin: cauldron on the south row with a mirror pane above it
  g.set(26, 2, 16, CAULDRON);
  g.set(26, 3, 16, GLASS_PANE);
  g.set(26, 4, 16, GLASS_PANE);
  // WC: quartz stairs with the seat facing into the room (north), and a cistern block against the south wall
  g.set(27, 2, 16, SMOOTH_QUARTZ_STAIRS, { facing: "north", half: "bottom" });
  g.set(27, 3, 16, SMOOTH_QUARTZ);
  g.set(27, 4, 16, SMOOTH_QUARTZ);
  // light: a sea_lantern hung from the spruce ceiling over the tub (the focal piece), and one over the WC
  g.set(26, 4, 14, SEA_LANTERN);
  g.set(27, 4, 15, SEA_LANTERN);
}

